'use strict';

const fs = require('fs');
const { buildRuntimeActions } = require('../geelooy/apps/tunnel/agent/tools/fs/actionGroups/runtimeActions.js');

/**
 * Chapter 1: The small vessel enters Merkava.
 * This runner feeds a real geelooy/ai file into simulateRuntime through the
 * Merkava executor parameters: runtime, engine, entry, files, probes, waitMs,
 * timeoutMs, origin, and url. No shell quoting storm is allowed to devour it.
 */
async function main() {
  const promptSource = fs.readFileSync('geelooy/ai/prompt.js', 'utf8');
  const files = {
    'index.html': '<main id="root"></main><script type="module" src="./prompt-check.js"></script>',
    'prompt.js': promptSource,
    'prompt-check.js': [
      'import { AwtsmoosPrompt } from "./prompt.js";',
      'globalThis.__promptExportType = typeof AwtsmoosPrompt;',
      'AwtsmoosPrompt.go({ isAlert: true, headerTxt: "<p id=\\"bh-probe\\">BH Merkava Prompt Test</p>" });',
      'console.log("prompt-export", globalThis.__promptExportType);'
    ].join('\n')
  };

  const payload = {
    action: 'simulateRuntime',
    runtime: 'browser',
    engine: 'merkava',
    entry: 'index.html',
    files,
    probes: [
      'globalThis.__promptExportType',
      'document.querySelector("#bh-probe")?.textContent',
      'document.querySelector(".awtsmoos-local-prompt-overlay")?.className'
    ],
    waitMs: 700,
    timeoutMs: 30000,
    origin: 'http://localhost:8080',
    url: 'http://localhost:8080'
  };

  const result = await buildRuntimeActions({ config: { root: process.cwd() }, payload }).simulateRuntime();
  console.log(JSON.stringify({
    ok: result.ok !== false,
    engine: result.engine,
    runtime: result.runtime,
    entry: result.entry,
    score: result.score,
    errors: result.errors,
    message: result.message,
    probes: result.variableSnapshots,
    domText: result.domSnapshot?.documentElement?.textContent?.slice?.(0, 240),
    moduleGraph: result.moduleGraph,
    assetGraph: result.assetGraph
  }, null, 2));
}

main().catch(error => {
  console.error(error && (error.stack || error.message) || String(error));
  process.exit(1);
});

